SELECT block_number,hex(block_hash) AS block_hash_hex,hex(manifest_hash) AS manifest_hash_hex,hex(batch_id) AS batch_id_hex,hex(quote_members) AS quote_members_hex,block_time,capture_mode,canonical,finality,quote_coverage,expected_quotes,actual_quotes,committed FROM dex_block FINAL WHERE chain_id=1 AND manifest_hash=unhex('e5493d29bf16f2d7665e90163eda323e2e7a2847e4bd3e7563db77ac11bfe567') AND block_time>='2026-10-01 15:00:00' AND block_time<'2026-10-01 17:00:00' ORDER BY block_number FORMAT JSONEachRow
